USE campusconnect;
CREATE TABLE IF NOT EXISTS courses(id INT AUTO_INCREMENT PRIMARY KEY,course_code VARCHAR(30) NOT NULL UNIQUE,title VARCHAR(180) NOT NULL,description TEXT,instructor VARCHAR(120) DEFAULT '',schedule_day VARCHAR(15) DEFAULT NULL,start_time TIME DEFAULT NULL,end_time TIME DEFAULT NULL,room VARCHAR(100) DEFAULT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS enrollments(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,course_id INT NOT NULL,UNIQUE KEY uq_enroll(user_id,course_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS announcements(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS events(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,event_date DATE NOT NULL,location VARCHAR(180) DEFAULT '',description TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS resources(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,category VARCHAR(80) DEFAULT 'General',description TEXT,url VARCHAR(1000) DEFAULT '',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS grades(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,course_id INT NOT NULL,assessment VARCHAR(160) NOT NULL,grade DECIMAL(5,2) NOT NULL,remarks VARCHAR(255) DEFAULT '',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS messages(id INT AUTO_INCREMENT PRIMARY KEY,sender_id INT NOT NULL,recipient_id INT NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS support_tickets(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,subject VARCHAR(180) NOT NULL,body TEXT NOT NULL,status ENUM('Open','Closed') DEFAULT 'Open',response TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
